import{_ as o,l,o as e,c as r,v as i,p as s,x as t,d as p,i as n,S as d}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"Linux capabilities","description":"","frontmatter":{"title":"Linux capabilities","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/linux-capabilities.md","filePath":"cs/linux-capabilities.md","lastUpdated":1789023840000}'),u={name:"cs/linux-capabilities.md"};function h(_,a,b,f,m,E){const c=l("Mermaid");return e(),r("div",null,[a[1]||(a[1]=i('<h1 id="linux-capabilities" tabindex="-1">Linux capabilities <a class="header-anchor" href="#linux-capabilities" aria-label="Permalink to &quot;Linux capabilities&quot;">​</a></h1><div class="epigraph"><p>capabilities 把 root 切成可单独授予的位：绑定低端口、加载模块、改时钟各占一位，进程不必再拿完整 uid 0。</p><footer>—— 据 POSIX 1003.1e 草案直觉；Linux capabilities(7)；[内核加固](/cs/kernel-hardening) 为利用缓解对照</footer></div><p><a href="/cs/timer-wheel">上一课</a>收口调度。<a href="/cs/kernel-user">用户/内核</a> 用 uid。缺口是 <strong>把超级用户拆成位图</strong>：bounding set、ambient、file capabilities。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>传统：uid 0 全能。cap：<code>CAP_NET_BIND_SERVICE</code> 即可 <code>:80</code>。缺口：effective/permitted/inheritable 三集合；execve 如何算新集；<code>CAP_SYS_ADMIN</code> 仍过大。本课不把每一位 man 页抄完。</p><p><span class="marginnote">文件能力：给二进制标 cap，不必 suid root。容器常 drop 再加回少数位。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>内核在特权检查处查 <code>capable()</code>。对照 LSM：cap 是粗粒度特权，LSM 是强制访问。对照 [seccomp]：seccomp 滤系统调用，cap 滤特权操作。对照 <a href="/cs/dm-crypt">dm-crypt</a>：解锁盘可能要 cap 或 uid。</p>',8)),(e(),s(d,null,{default:t(()=>[n(c,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20OLD%5B%22uid%200%20%E5%85%A8%E8%83%BD%22%5D%20--%3E%20CAP%5B%22%E4%BD%8D%E5%9B%BE%E7%89%B9%E6%9D%83%22%5D%0A%20%20EXEC%5B%22execve%22%5D%20--%3E%20CALC%5B%22%E8%AE%A1%E7%AE%97%E6%96%B0%20cap%20%E9%9B%86%22%5D%0A%20%20CHK%5B%22%E7%89%B9%E6%9D%83%E6%93%8D%E4%BD%9C%22%5D%20--%3E%20EFF%5B%22effective%20%E4%BD%8D%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>capabilities 缩小攻击面：被攻破的守护不必带完整 root。残留的 <code>SYS_ADMIN</code> 说明拆分不彻底。不要写成云 IAM。与 <a href="/cs/userfaultfd">userfaultfd</a>：操作别人地址空间另要 ptrace 等，不单是 cap。</p><p>调试：<code>getpcaps</code>、<code>/proc/self/status</code> 的 Cap 行。</p><p>实现上：bounding set 限制能获得的 cap，容器常用它做不可再加。ambient 让非 root 执行文件后仍留住某些 cap。CAP_SYS_ADMIN 几乎等于旧 root，拆分失败就在这里。 读法上只引用<a href="/cs/timer-wheel">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「安全、启动与调试 / 内核安全与启动」课序里，对象是 <strong>Linux capabilities</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入命名空间里 cap 的全部映射。不保证 Android 的额外位。下一课强制访问：LSM 与 SELinux。</p><p>版本字段会变，课序钉的是机制对象「Linux capabilities」，不是某一主线内核的结构体名。 后课默认：特权是位，不是单一 root。LSM 钩子与 SELinux 标签，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>capabilities 把 root 拆成可丢弃的位。</li><li>exec 与文件 cap 决定子进程特权。</li><li>LSM/SELinux 是下一课。</li><li>出处：Linux <code>capabilities(7)</code>；POSIX 草案；内核 security。</li></ul>',11))])}const A=o(u,[["render",h]]);export{S as __pageData,A as default};
